<?php
trait YellowSectioneditPart6 {
function parseAtxHeading($line) { if (!preg_match('/^ {0,3}(#{1,6})(?:[ \t]+|$)(.*)$/', $line, $m)) return null; return array("level" => strlen($m[1]), "title" => $m[2], "startLine" => null); }
function cleanAtxTitle($title) { $title = rtrim($title); $title = preg_replace('/[ \t]+#+[ \t]*$/', '', $title); return trim($title); }
function getFrontMatterEnd($lines) { if (count($lines) === 0) return 0; $first = ltrim($lines[0]["text"], "\xEF\xBB\xBF"); if (trim($first) !== "---") return 0; for ($i = 1; $i < count($lines); $i++) if (trim($lines[$i]["text"]) === "---") return $i + 1; return 0; }
function getLines($text) { $lines = array(); $length = strlen($text); $start = 0; while ($start < $length) { $p = preg_match('/\r\n|\r|\n/', $text, $m, PREG_OFFSET_CAPTURE, $start); if (!$p) { $lines[] = array("text" => substr($text, $start), "start" => $start, "end" => $length); $start = $length; break; } $nlStart = $m[0][1]; $nlLen = strlen($m[0][0]); $lines[] = array("text" => substr($text, $start, $nlStart - $start), "start" => $start, "end" => $nlStart + $nlLen); $start = $nlStart + $nlLen; } if ($length === 0 || ($length > 0 && preg_match('/\r\n|\r|\n$/', $text))) $lines[] = array("text" => "", "start" => $length, "end" => $length); return $lines; }
function getCss() { return '.sectionedit-body{font-family:var(--font,"Open Sans",Helvetica,sans-serif);font-size:1em;font-weight:300;line-height:1.5}.sectionedit{position:relative;display:block;box-sizing:border-box;width:100%;max-width:1100px;margin:1em auto 0;padding:10px;background-color:#fff;color:#000;border:1px solid #bbb;border-radius:4px;box-shadow:2px 4px 10px rgba(0,0,0,.2);text-align:left}.sectionedit form{margin:0}.sectionedit-toolbar-main{margin-left:8px}.sectionedit .yellow-edit-text{box-sizing:border-box;width:100%;min-height:65vh;padding:0 2px;outline:none;resize:none;border:0;background:transparent;color:inherit;font-size:.9em;font-family:inherit;font-weight:normal;line-height:normal;display:block;overflow:auto}.sectionedit .yellow-edit-preview{box-sizing:border-box;width:100%;min-height:65vh;padding:0;overflow:auto;border:0;background:#fff}.sectionedit .yellow-toolbar-btn-icon{cursor:pointer}.sectionedit .yellow-toolbar-btn-icon:hover{cursor:pointer}'; }
}
